css:
.mediums { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin: 18px 0 6px; }
  .medium { padding: 16px 18px; border-radius: 14px; background: #fff; border: 1px solid var(--line); }
  .medium small { display: block; font-size: 11.5px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: var(--green); margin-bottom: 6px; }
  .medium p { margin: 0; font-family: var(--serif); font-size: 17px; line-height: 1.4; color: var(--ink); }
  .signals { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 16px; }
  .signals div { padding: 14px 16px; border-radius: 12px; background: var(--cream-2); font-size: 15px; }
  .signals b { display: block; font-weight: 600; margin-bottom: 2px; }
  @media (max-width: 820px) { .mediums, .signals { grid-template-columns: 1fr; } }
